from flask import Flask, render_template_string, jsonify, request
from flask_socketio import SocketIO, emit
from pyecharts.charts import Line, Bar, Pie, Grid
from pyecharts import options as opts
import threading
import time
import random

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret!'
socketio = SocketIO(app)

# 模拟数据
categories = ['A', 'B', 'C', 'D']
current_filter = None

def generate_data():
    data = []
    for cat in categories:
        data.append({
            'category': cat,
            'value1': random.randint(10, 100),
            'value2': random.randint(10, 100),
            'value3': random.randint(10, 100)
        })
    return data

dashboard_data = generate_data()

def make_line_chart(data, filter_cat=None):
    if filter_cat:
        data = [d for d in data if d['category'] == filter_cat]
    line = (
        Line()
        .add_xaxis([d['category'] for d in data])
        .add_yaxis('数值1', [d['value1'] for d in data])
        .set_global_opts(title_opts=opts.TitleOpts(title='折线图'))
    )
    return line

def make_bar_chart(data):
    bar = (
        Bar()
        .add_xaxis([d['category'] for d in data])
        .add_yaxis('数值2', [d['value2'] for d in data])
        .set_global_opts(title_opts=opts.TitleOpts(title='柱状图（点击联动）'))
    )
    return bar

def make_pie_chart(data, filter_cat=None):
    if filter_cat:
        data = [d for d in data if d['category'] == filter_cat]
    pie = (
        Pie()
        .add('', [[d['category'], d['value3']] for d in data])
        .set_global_opts(title_opts=opts.TitleOpts(title='饼图'))
    )
    return pie

def make_grid(data, filter_cat=None):
    line = make_line_chart(data, filter_cat)
    bar = make_bar_chart(data)
    pie = make_pie_chart(data, filter_cat)
    grid = (
        Grid()
        .add(line, grid_opts=opts.GridOpts(pos_left="10%", pos_right="55%", pos_top="10%", pos_bottom="50%"))
        .add(bar, grid_opts=opts.GridOpts(pos_left="55%", pos_right="5%", pos_top="10%", pos_bottom="50%"))
        .add(pie, grid_opts=opts.GridOpts(pos_left="10%", pos_right="5%", pos_top="55%", pos_bottom="5%"))
    )
    return grid

@app.route('/')
def index():
    grid = make_grid(dashboard_data)
    chart_html = grid.render_embed()
    html = f'''
    <!DOCTYPE html>
    <html>
    <head><title>仪表盘</title></head>
    <body>
        <div class="card" id="chart_container">{chart_html}</div>
        <script src="https://cdn.socket.io/4.5.0/socket.io.min.js"></script>
        <script>
            window.addEventListener('resize', function() {{
                var chart = echarts.getInstanceByDom(document.getElementById('chart_container').getElementsByTagName('div')[0]);
                if (chart) chart.resize();
            }});
            var socket = io();
            socket.on('update_data', function(data) {{
                // 实时更新逻辑：重新获取图表并刷新
                location.reload();
            }});
            // 柱状图点击联动
            var barChartDom = document.querySelectorAll('.chart')[1];
            var barChart = echarts.getInstanceByDom(barChartDom);
            barChart.on('click', function(params) {{
                var cat = params.name;
                fetch('/filter?cat=' + cat)
                    .then(response => response.text())
                    .then(html => {{
                        document.getElementById('chart_container').innerHTML = html;
                    }});
            }});
        </script>
    </body>
    </html>
    '''
    return render_template_string(html)

@app.route('/filter')
def filter_data():
    cat = request.args.get('cat')
    grid = make_grid(dashboard_data, filter_cat=cat)
    return grid.render_embed()

@app.route('/api/data', methods=['GET'])
def api_data():
    start = request.args.get('start')
    end = request.args.get('end')
    # 模拟时间范围筛选（此处忽略，实际可过滤）
    return jsonify(dashboard_data)

def background_task():
    while True:
        time.sleep(5)
        global dashboard_data
        dashboard_data = generate_data()
        socketio.emit('update_data', dashboard_data)

if __name__ == '__main__':
    threading.Thread(target=background_task, daemon=True).start()
    socketio.run(app, debug=True)
